     } else kputc_('.', s);
     kputc_('\t', s); // QUAL
     if ( bcf_float_is_missing(v->qual) ) kputc_('.', s); // QUAL
     else kputd(v->qual, s);
     kputc_('\t', s); // FILTER
     if (v->d.n_flt) {
         for (i = 0; i < v->d.n_flt; ++i) {
             int32_t idx = v->d.flt[i];
             if (idx < 0 || idx >= max_dt_id
                 || h->id[BCF_DT_ID][idx].key == NULL) {
                 hts_log_error("Invalid BCF, the FILTER tag id=%d at %s:%"PRIhts_pos" not present in the header",
                               idx, bcf_seqname_safe(h, v), v->pos + 1);
                 errno = EINVAL;
                 return -1;
             }
             if (i) kputc_(';', s);
             if (!key_len[idx])
                 key_len[idx] = strlen(h->id[BCF_DT_ID][idx].key);
             kputsn(h->id[BCF_DT_ID][idx].key, key_len[idx], s);
         }
     } else kputc_('.', s);

     kputc_('\t', s); // INFO
     if (v->n_info) {
-        uint8_t *ptr = (uint8_t *)v->shared.s + v->unpack_size[0] + v->unpack_size[1] + v->unpack_size[2];
+        uint8_t *ptr = v->shared.s
+            ? (uint8_t *)v->shared.s + v->unpack_size[0] +
+               v->unpack_size[1] + v->unpack_size[2]
+            : NULL;
         int first = 1;
         bcf_info_t *info = v->d.info;

         // Note if we duplicate this code into custom packed and unpacked
         // implementations then we gain a bit more speed, particularly with
         // clang 13 (up to 5%).  Not sure why this is, but code duplication
         // isn't pleasant and it's still faster adding packed support than
         // not so it's a win, just not as good as it should be.
         const int info_packed = !(v->unpacked & BCF_UN_INFO) && v->shared.l;
         for (i = 0; i < v->n_info; ++i) {
             bcf_info_t in, *z;
             if (info_packed) {
                 // Use a local bcf_info_t when data is packed
                 z = &in;
                 z->key  = bcf_dec_typed_int1(ptr, &ptr);
                 z->len  = bcf_dec_size(ptr, &ptr, &z->type);
                 z->vptr = ptr;
                 ptr += z->len << bcf_type_shift[z->type];
             } else {
                 // Else previously unpacked INFO struct
                 z = &info[i];

                 // Also potentially since deleted
                 if ( !z->vptr ) continue;
             }

             bcf_idpair_t *id = z->key >= 0 && z->key < max_dt_id
                 ? &h->id[BCF_DT_ID][z->key]
                 : NULL;

             if (!id || !id->key) {
                 hts_log_error("Invalid BCF, the INFO tag id=%d is %s at %s:%"PRIhts_pos,
                               z->key,
                               z->key < 0 ? "negative"
                               : (z->key >= max_dt_id ? "too large" : "not present in the header"),
                               bcf_seqname_safe(h, v), v->pos+1);
                 errno = EINVAL;
                 return -1;
             }

             // KEY
             if (!key_len[z->key])
                 key_len[z->key] = strlen(id->key);
             size_t id_len = key_len[z->key];
             if (ks_resize(s, s->l + 3 + id_len) < 0)
                 return -1;
             char *sptr = s->s + s->l;
             if ( !first ) {
                 *sptr++ = ';';
                 s->l++;
             }
             first = 0;
             memcpy(sptr, id->key, id_len);
             s->l += id_len;

             // VALUE
             if (z->len <= 0) continue;
             sptr[id_len] = '=';
             s->l++;

commit 3944da0922f8ef489c3fa38bc44bcf40f4e73dcc
Author: Rob Davies <rmd+git@sanger.ac.uk>
Date:   Wed Apr 21 12:20:41 2021 +0100

    Prevent endless aux_parse loop and avoid malformed aux data

    In lenient mode, skip the check for integer overflows.  Fixes an
    endless loop due to `overflow` not being reset, and by the time
    the check is made all the input data has been used so trying to
    loop back won't do anything useful.

    Make the _parse_err() macro in aux_parse() reset `b->l_data` to
    where it was at the start of the loop if it detects an error in
    lenient mode.  This cleans up any semi-formed aux records that
    may be present before the parser tries to skip to the next tag.

diff --git a/sam.c b/sam.c
index b6337202..8a3f8c34 100644
--- a/sam.c
+++ b/sam.c
@@ -2348,249 +2348,252 @@ static int sam_parse_B_vals(char type, uint32_t n, char *in, char **end,
             if (max < val) max = val;
             if (min > val) min = val;
             skip_to_comma_(q);
         }
         // Retry with appropriate type
         if (!overflow) {
             if (min < 0) {
                 if (min >= INT8_MIN && max <= INT8_MAX) {
                     return sam_parse_B_vals('c', n, in, end, r, b);
                 } else if (min >= INT16_MIN && max <= INT16_MAX) {
                     return sam_parse_B_vals('s', n, in, end, r, b);
                 } else if (min >= INT32_MIN && max <= INT32_MAX) {
                     return sam_parse_B_vals('i', n, in, end, r, b);
                 }
             } else {
                 if (max < UINT8_MAX) {
                     return sam_parse_B_vals('C', n, in, end, r, b);
                 } else if (max <= UINT16_MAX) {
                     return sam_parse_B_vals('S', n, in, end, r, b);
                 } else if (max <= UINT32_MAX) {
                     return sam_parse_B_vals('I', n, in, end, r, b);
                 }
             }
         }
         // If here then at least one of the values is too big to store
         hts_log_error("Numeric value in B array out of allowed range");
         return -1;
     }
 #undef skip_to_comma_
 }

 static inline unsigned int parse_sam_flag(char *v, char **rv, int *overflow) {
     if (*v >= '1' && *v <= '9') {
         return hts_str2uint(v, rv, 16, overflow);
     }
     else if (*v == '0') {
         // handle single-digit "0" directly; otherwise it's hex or octal
         if (v[1] == '\t') { *rv = v+1; return 0; }
         else {
             unsigned long val = strtoul(v, rv, 0);
             if (val > 65535) { *overflow = 1; return 65535; }
             return val;
         }
     }
     else {
         // TODO implement symbolic flag letters
         *rv = v;
         return 0;
     }
 }

 // Parse tag line and append to bam object b.
 // Shared by both SAM and FASTQ parsers.
 //
 // The difference between the two is how lenient we are to recognising
 // non-compliant strings.  The FASTQ parser glosses over arbitrary
 // non-SAM looking strings.
 static inline int aux_parse(char *start, char *end, bam1_t *b, int lenient,
                             khash_t(tag) *tag_whitelist) {
     int overflow = 0;
+    int checkpoint;
     char logbuf[40];
     char *q = start, *p = end;

 #define _parse_err(cond, ...)                   \
     do {                                        \
         if (cond) {                             \
             if (lenient) {                      \
                 while (q < p && !isspace_c(*q))   \
                     q++;                        \
                 while (q < p && isspace_c(*q))    \
                     q++;                        \
+                b->l_data = checkpoint;         \
                 goto loop;                      \
             } else {                            \
                 hts_log_error(__VA_ARGS__);     \
                 goto err_ret;                   \
             }                                   \
         }                                       \
     } while (0)

     while (q < p) loop: {
         char type;
+        checkpoint = b->l_data;
         if (p - q < 5) {
             if (lenient) {
                 break;
             } else {
                 hts_log_error("Incomplete aux field");
                 goto err_ret;
             }
         }
         _parse_err(q[0] < '!' || q[1] < '!', "invalid aux tag id");

         if (lenient && (q[2] | q[4]) != ':') {
             while (q < p && !isspace_c(*q))
                 q++;
             while (q < p && isspace_c(*q))
                 q++;
             continue;
         }

         if (tag_whitelist) {
             int tt = q[0]*256 + q[1];
             if (kh_get(tag, tag_whitelist, tt) == kh_end(tag_whitelist)) {
                 while (q < p && *q != '\t')
                     q++;
                 continue;
             }
         }

         // Copy over id
         if (possibly_expand_bam_data(b, 2) < 0) goto err_ret;
         memcpy(b->data + b->l_data, q, 2); b->l_data += 2;
         q += 3; type = *q++; ++q; // q points to value
         if (type != 'Z' && type != 'H') // the only zero length acceptable fields
             _parse_err(*q <= '\t', "incomplete aux field");

         // Ensure enough space for a double + type allocated.
         if (possibly_expand_bam_data(b, 16) < 0) goto err_ret;

         if (type == 'A' || type == 'a' || type == 'c' || type == 'C') {
             b->data[b->l_data++] = 'A';
             b->data[b->l_data++] = *q++;
         } else if (type == 'i' || type == 'I') {
             if (*q == '-') {
                 int32_t x = hts_str2int(q, &q, 32, &overflow);
                 if (x >= INT8_MIN) {
                     b->data[b->l_data++] = 'c';
                     b->data[b->l_data++] = x;
                 } else if (x >= INT16_MIN) {
                     b->data[b->l_data++] = 's';
                     i16_to_le(x, b->data + b->l_data);
                     b->l_data += 2;
                 } else {
                     b->data[b->l_data++] = 'i';
                     i32_to_le(x, b->data + b->l_data);
                     b->l_data += 4;
                 }
             } else {
                 uint32_t x = hts_str2uint(q, &q, 32, &overflow);
                 if (x <= UINT8_MAX) {
                     b->data[b->l_data++] = 'C';
                     b->data[b->l_data++] = x;
                 } else if (x <= UINT16_MAX) {
                     b->data[b->l_data++] = 'S';
                     u16_to_le(x, b->data + b->l_data);
                     b->l_data += 2;
                 } else {
                     b->data[b->l_data++] = 'I';
                     u32_to_le(x, b->data + b->l_data);
                     b->l_data += 4;
                 }
             }
         } else if (type == 'f') {
             b->data[b->l_data++] = 'f';
             float_to_le(strtod(q, &q), b->data + b->l_data);
             b->l_data += sizeof(float);
         } else if (type == 'd') {
             b->data[b->l_data++] = 'd';
             double_to_le(strtod(q, &q), b->data + b->l_data);
             b->l_data += sizeof(double);
         } else if (type == 'Z' || type == 'H') {
             char *end = strchr(q, '\t');
             if (!end) end = q + strlen(q);
             _parse_err(type == 'H' && ((end-q)&1) != 0,
                        "hex field does not have an even number of digits");
             b->data[b->l_data++] = type;
             if (possibly_expand_bam_data(b, end - q + 1) < 0) goto err_ret;
             memcpy(b->data + b->l_data, q, end - q);
             b->l_data += end - q;
             b->data[b->l_data++] = '\0';
             q = end;
         } else if (type == 'B') {
             uint32_t n;
             char *r;
             type = *q++; // q points to the first ',' following the typing byte
             _parse_err(*q && *q != ',' && *q != '\t',
                        "B aux field type not followed by ','");

             for (r = q, n = 0; *r > '\t'; ++r)
                 if (*r == ',') ++n;

             if (sam_parse_B_vals(type, n, q, &q, r, b) < 0)
                 goto err_ret;
         } else _parse_err(1, "unrecognized type %s", hts_strprint(logbuf, sizeof logbuf, '\'', &type, 1));

         while (*q > '\t') { q++; } // Skip any junk to next tab
         q++;
     }

-    _parse_err(overflow != 0, "numeric value out of allowed range");
+    _parse_err(!lenient && overflow != 0, "numeric value out of allowed range");
 #undef _parse_err

     return 0;

 err_ret:
     return -2;
 }

 int sam_parse1(kstring_t *s, sam_hdr_t *h, bam1_t *b)
 {
 #define _read_token(_p) (_p); do { char *tab = strchr((_p), '\t'); if (!tab) goto err_ret; *tab = '\0'; (_p) = tab + 1; } while (0)

 #if HTS_ALLOW_UNALIGNED != 0 && ULONG_MAX == 0xffffffffffffffff

 // Macro that operates on 64-bits at a time.
 #define COPY_MINUS_N(to,from,n,l,failed)                        \
     do {                                                        \
         uint64_u *from8 = (uint64_u *)(from);                   \
         uint64_u *to8 = (uint64_u *)(to);                       \
         uint64_t uflow = 0;                                     \
         size_t l8 = (l)>>3, i;                                  \
         for (i = 0; i < l8; i++) {                              \
             to8[i] = from8[i] - (n)*0x0101010101010101UL;       \
             uflow |= to8[i];                                    \
         }                                                       \
         for (i<<=3; i < (l); ++i) {                             \
             to[i] = from[i] - (n);                              \
             uflow |= to[i];                                     \
         }                                                       \
         failed = (uflow & 0x8080808080808080UL) > 0;            \
     } while (0)

 #else

 // Basic version which operates a byte at a time
 #define COPY_MINUS_N(to,from,n,l,failed) do {                \
         uint8_t uflow = 0;                                   \
         for (i = 0; i < (l); ++i) {                          \
             (to)[i] = (from)[i] - (n);                       \
             uflow |= (uint8_t) (to)[i];                      \
         }                                                    \
         failed = (uflow & 0x80) > 0;                         \
     } while (0)

 #endif

 #define _get_mem(type_t, x, b, l) if (possibly_expand_bam_data((b), (l)) < 0) goto err_ret; *(x) = (type_t*)((b)->data + (b)->l_data); (b)->l_data += (l)
 #define _parse_err(cond, ...) do { if (cond) { hts_log_error(__VA_ARGS__); goto err_ret; } } while (0)
 #define _parse_warn(cond, ...) do { if (cond) { hts_log_warning(__VA_ARGS__); } } while (0)

     uint8_t *t;

     char *p = s->s, *q;
     int i, overflow = 0;
     char logbuf[40];
     hts_pos_t cigreflen;
     bam1_core_t *c = &b->core;

     b->l_data = 0;
     memset(c, 0, 32);
